package cl.duoc.tienda.resena.controller;
import cl.duoc.tienda.resena.dto.*; import cl.duoc.tienda.resena.model.*; import cl.duoc.tienda.resena.service.*; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.net.URI; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/resenas") @Tag(name="Resena",description="CRUD de resenas") public class ResenaController { private final ResenaService service; public ResenaController(ResenaService s){service=s;} @GetMapping @Operation(summary="Listar resenas") public ResponseEntity<List<Resena>> listar(){return ResponseEntity.ok(service.listar());} @GetMapping("/{id}") public ResponseEntity<Resena> buscar(@PathVariable Long id){return ResponseEntity.ok(service.buscar(id));} @PostMapping public ResponseEntity<Resena> crear(@Valid @RequestBody ResenaRequest d){Resena e=service.guardar(d);return ResponseEntity.created(URI.create("/resenas/"+e.getId())).body(e);} @PutMapping("/{id}") public ResponseEntity<Resena> actualizar(@PathVariable Long id,@Valid @RequestBody ResenaRequest d){return ResponseEntity.ok(service.actualizar(id,d));} @DeleteMapping("/{id}") public ResponseEntity<Void> eliminar(@PathVariable Long id){service.eliminar(id);return ResponseEntity.noContent().build();} }
